  display: inline-block;
  line-height: 100%;
  height: 80px;
  width: 80px !important;
  border-radius: 100%;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  padding: 4px;
  transition: 0.4s;
}
.rbt-swiper-thumb .swiper-slide::before {
  content: "";
  z-index: -1;
  top: 0;
  left: 0;
  position: absolute;
  background: var(--color-white);
  width: 100%;
  height: 100%;
  transition: 0.4s;
}
.rbt-swiper-thumb .swiper-slide::after {
  content: "";
  z-index: -1;
  top: 0;
  left: 0;
  position: absolute;
  background: #000;
  width: 100%;
  height: 100%;
  opacity: 0.2;
  transition: 0.4s;
}
